def can_finish(n, prerequisites):
    indeg, nxt = [0] * n, [[] for _ in range(n)]
    for a, b in prerequisites:
        nxt[b].append(a)
        indeg[a] += 1
    q, done = deque(i for i in range(n) if indeg[i] == 0), 0
    while q:
        u = q.popleft()
        done += 1
        for v in nxt[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    return done == n

